mapper.select:
    select

    ,
                  bri2.name as parent_name
from base_region_info bri
         left join base_region_info bri2
                   on bri.parent_id = bri2.id


            and bri.id = #{id}


            and bri.name like concat('%'
                , #{name}
                , '%')


            and bri.parent_id = #{parentId}


            and bri2.name like concat('%'
                , #{parentName}
                , '%')


            and bri.levels = #{levels}


    order by bri.id desc
